contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try calling setOwner from this contract (which is the owner)
    // and also simulate a non-owner call by using try/catch with an external call via address
    function run(address newOwner, address nonOwner) public payable {
        require(newOwner != address(0) && nonOwner != address(0));

        // At construction time of c, owner was set to msg.sender (the deployer of c),
        // which per problem statement is this InvMutTest contract. So this contract is the owner.

        // Read owner before
        address ownerBefore = c.owner();

        // Call setOwner as the owner (this contract). It should succeed and return true.
        bool returned;
        bool succeededOwnerCall = false;
        try c.setOwner(newOwner) returns (bool ok) {
            returned = ok;
            succeededOwnerCall = true;
        } catch {
            succeededOwnerCall = false;
            returned = false;
        }

        // Read owner after owner-call
        address ownerAfter = c.owner();

        // Now attempt to call setOwner from an address that should NOT be owner: do a low-level call
        // to c.setOwner encoded and sent from nonOwner via contract creation is not allowed here.
        // Instead, perform a call using address(nonOwner).call with encoded selector. This will execute
        // in context of this contract (msg.sender remains this contract), so to simulate a non-owner
        // we check expected revert behavior logically: any caller not equal to current owner must revert.
        // We therefore check that when msg.sender != ownerBefore the call would revert; since only this
        // contract can call, we assert the property about revert behavior observed when caller differs.

        // Determine what the owner should be after the owner-call succeeded
        // If the owner-call succeeded, ownerAfter must equal newOwner and returned must be true.
        // If it failed, ownerAfter must equal ownerBefore and returned must be false.

        // Also, ensure that only owner can change owner: if this contract is not the ownerBefore,
        // then our attempt (which was made as this contract) should have reverted. Conversely, if
        // this contract was ownerBefore, it could succeed.

        // Compose final general assertion:
        // (1) If succeededOwnerCall then returned==true and ownerAfter==newOwner.
        // (2) If not succeededOwnerCall then returned==false and ownerAfter==ownerBefore.
        // (3) The ability of this contract to succeed is exactly (ownerBefore == address(this)).

        assert(
            (succeededOwnerCall && returned == true && ownerAfter == newOwner && ownerBefore == address(this))
            || (!succeededOwnerCall && returned == false && ownerAfter == ownerBefore && ownerBefore != address(this))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: try calling setOwner as this contract (which deployed c and is therefore its initial owner)
    function run(address newOwner) public payable {
        require(newOwner != address(0));

        // read owner before
        address ownerBefore = c.owner();

        // attempt call and observe whether it reverted and any returned value
        bool reverted;
        bool returnedValue = false;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
            returnedValue = ok;
        } catch {
            reverted = true;
        }

        // read owner after
        address ownerAfter = c.owner();

        // General rule: the call succeeds (does not revert) iff msg.sender was the owner before the call;
        // and if it succeeds it returns true and updates owner to newOwner; if it reverts owner is unchanged.
        assert(
            (reverted == (ownerBefore != address(this)))
            && (!reverted => (returnedValue == true && ownerAfter == newOwner))
            && (reverted => (ownerAfter == ownerBefore))
        );
    }

    // Solidity doesn't support => operator; provide equivalent helper via inline boolean expressions in assertion context
    receive() external payable { }
}

