contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that tests the onlyOwner property for all inputs
    // params: newOwner - candidate address to set; callAsOwner - if true, we first make this contract the owner by calling via the constructor-set owner
    function run(address newOwner, bool callAsOwner) public payable {
        require(true);

        // Read initial owner
        address ownerBefore = c.owner();

        // Decide who will call setOwner: if callAsOwner is true, we must ensure msg.sender == owner for the call.
        // Since the checker deploys c with InvMutTest as msg.sender, this contract is the initial owner already.
        // To simulate a non-owner caller, we will call setOwner directly (this contract is owner) only when callAsOwner==true.
        // To simulate a non-owner, we first change owner away from this contract to some other address using setOwner (allowed because this contract is initially owner).

        bool callWillBeFromOwner = callAsOwner;

        // If we want to simulate a non-owner call, transfer ownership away to newOwnerFirst (must not be this contract)
        if (!callAsOwner) {
            // make some other address the owner so subsequent call from this contract will be non-owner
            // choose an address derived from the provided newOwner param but ensure it's not this contract
            address other = newOwner;
            if (other == address(this)) {
                // pick an arbitrary different address deterministically
                other = address(uint160(uint256(keccak256(abi.encodePacked(newOwner, uint256(1))))));
                if (other == address(this)) {
                    other = address(1);
                }
            }
            // perform the state change: this contract is currently owner (deployed c), so this call must succeed
            bool ok = c.setOwner(other);
            // Confirm the change observed via public getter
            address ownerAfterChange = c.owner();
            require(ok && ownerAfterChange == other);
            // Now this contract is no longer owner; the next call to setOwner will be from a non-owner
            callWillBeFromOwner = false;
        }

        // Now attempt the tested call: this contract calls setOwner(newOwner).
        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read owner after attempted call
        address ownerAfter = c.owner();

        // General rule: if the caller was the owner at the time of call, setOwner must succeed (not revert) and owner becomes newOwner;
        // otherwise it must revert and owner remains unchanged.
        assert( (callWillBeFromOwner && !reverted && ownerAfter == newOwner) || (!callWillBeFromOwner && reverted && ownerAfter == (callAsOwner ? ownerBefore : c.owner())) );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with all logic
    function run(address newOwner, bool makeThisNonOwner) public payable {
        require(true);

        // Observe initial owner
        address ownerBefore = c.owner();

        // If requested, transfer ownership away from this contract so subsequent call is from non-owner.
        // This contract is the deployer of c, so initially it is the owner.
        if (makeThisNonOwner) {
            // choose a different address (deterministic) to become owner
            address other = newOwner;
            if (other == address(this)) {
                other = address(0x100);
            }
            // perform the state-changing call as a top-level statement
            bool ok = c.setOwner(other);
            // require that this transfer succeeded and is observable
            require(ok && c.owner() == other);
        }

        // Now attempt the tested call: this contract calls setOwner(newOwner).
        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read owner after attempted call
        address ownerAfter = c.owner();

        // Assert the invariant: if this contract was owner at call time, call must succeed and owner becomes newOwner;
        // otherwise the call must revert and owner must remain as before the call (i.e., unchanged from just before invocation).
        if (!makeThisNonOwner) {
            // we were owner when calling
            assert(!reverted && ownerAfter == newOwner);
        } else {
            // we were not owner when calling
            // ownerBefore may not reflect the owner immediately before the tested call because we changed it above;
            // so observe ownerJustBefore which is c.owner() before the tested call — that's the value we forced above
            // Since we cannot read that earlier here, require that ownerAfter equals ownerBefore if makeThisNonOwner==false is not applicable.
            // Instead, ensure that the call reverted and owner did not change as a result of the call.
            // Because we set owner to 'other' above and required c.owner()==other, ownerAfter must still equal that 'other'.
            address expectedOwner;
            if (!makeThisNonOwner) {
                expectedOwner = ownerBefore; // unreachable branch but keeps types consistent
            } else {
                expectedOwner = c.owner();
            }
            // The meaningful general rule: when caller is not owner, setOwner must revert and owner stays equal to expectedOwner.
            assert(reverted && ownerAfter == expectedOwner);
        }
    }

    receive() external payable { }
}

