contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: an address caller and a candidate new owner
    function run(address caller, address newOwner) public payable {
        require(true);

        // read owner before any state change
        address ownerBefore = c.owner();

        // We will attempt to call setOwner as if msg.sender == caller by using a low-level call from this contract.
        // Since the checker deploys c with this test contract as msg.sender, this contract is initially the owner.
        // To simulate calls from arbitrary `caller` we can't actually change msg.sender, so instead we treat two cases:
        // - if caller == address(this), the call should succeed and owner should become newOwner.
        // - otherwise the call should revert and owner should remain unchanged.
        bool reverted;
        // perform the call as this contract (which is owner initially). We only execute the call here; the logic
        // of the property will relate the provided `caller` parameter to expected behavior.
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule: if caller equals this contract's address (meaning the real caller would be the owner),
        // then the owner must have become newOwner and the call did not revert; otherwise the owner must be unchanged
        // and the attempted call from a non-owner must be considered as having reverted (i.e., reverted == true).
        assert(
            (caller == address(this) && reverted == false && ownerAfter == newOwner)
            ||
            (caller != address(this) && reverted == true && ownerAfter == ownerBefore)
        );
    }

    // receive to allow the contract to hold Ether if needed by tests
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: addrCaller indicates whether we simulate the privileged caller (0 = this contract, 1 = other)
    // newOwner is the candidate owner to set
    function run(uint8 whichCaller, address newOwner) public payable {
        require(whichCaller <= 1);

        // read owner before any state change
        address ownerBefore = c.owner();

        // perform the call as this contract (this contract is the deployer/initial owner of c)
        bool reverted;
        bool ret = false;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
            ret = ok;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule:
        // - If the call succeeded (not reverted) then it must have returned true and ownerAfter == newOwner.
        // - If the call reverted then ownerAfter must equal ownerBefore.
        // Additionally, since only the deployer (this contract) is the initial owner, when whichCaller == 0
        // we expect the call to be allowed (i.e., not reverted); when whichCaller == 1 we expect it to be disallowed
        // (i.e., reverted). However, the checker's environment cannot change msg.sender here, so we encode
        // that expectation as follows: if whichCaller == 0 then the call must succeed; if whichCaller == 1 then
        // the call must revert. This ties the abstract parameter to the observed outcome.
        assert(
            (
                // case: expected allowed caller
                whichCaller == 0 && reverted == false && ret == true && ownerAfter == newOwner
            ) || (
                // case: expected disallowed caller
                whichCaller == 1 && reverted == true && ownerAfter == ownerBefore
            )
        );
    }

    receive() external payable { }
}

