contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: candidate new owner and an address to act as caller is NOT possible
    // because msg.sender for calls to c will be this contract. We therefore check behavior when this contract
    // (which is the deployer of c) calls setOwner. We also try calling setOwner again after changing owner.
    function run(address newOwner, address anotherNewOwner) public payable {
        require(true);

        // Initially, the InvMutTest contract deployed c, so c.owner() should be this contract's address.
        address beforeOwner = c.owner();

        // Ensure that this contract is initially the owner (as per C's constructor when deployed by this contract).
        // If not, the following call would revert; we still capture revert behavior.
        bool firstReverted;
        bool firstReturned;
        try c.setOwner(newOwner) returns (bool ok) {
            firstReverted = false;
            firstReturned = ok;
        } catch {
            firstReverted = true;
            firstReturned = false;
        }

        // Read owner after first attempt
        address midOwner = c.owner();

        // Attempt a second change: try to set owner to anotherNewOwner. This will succeed only if this contract
        // is currently the owner (i.e., midOwner == address(this)). Capture revert/return.
        bool secondReverted;
        bool secondReturned;
        try c.setOwner(anotherNewOwner) returns (bool ok2) {
            secondReverted = false;
            secondReturned = ok2;
        } catch {
            secondReverted = true;
            secondReturned = false;
        }

        address afterOwner = c.owner();

        // General rule asserted:
        // - If the first call did not revert and returned true, then midOwner equals newOwner.
        // - If the first call reverted then midOwner equals beforeOwner (no change).
        // - Similarly for the second call: if it returned true then afterOwner equals anotherNewOwner,
        //   otherwise afterOwner equals midOwner.
        assert(
            ((firstReverted == false && firstReturned == true) ? (midOwner == newOwner) : (midOwner == beforeOwner))
            &&
            ((secondReverted == false && secondReturned == true) ? (afterOwner == anotherNewOwner) : (afterOwner == midOwner))
        );
    }

    receive() external payable {}
}

