contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public payable {
        // observe current owner
        address beforeOwner = c.owner();

        // attempt the state-changing call and record whether it reverted and returned value
        bool didRevert;
        bool returnedTrue;
        try c.setOwner(newOwner) returns (bool ok) {
            didRevert = false;
            returnedTrue = ok;
        } catch {
            didRevert = true;
            returnedTrue = false;
        }

        // observe owner after
        address afterOwner = c.owner();

        // General property:
        // If this contract was the owner before the call, the call must not revert, must return true,
        // and owner must equal the provided newOwner. If this contract was not the owner before the call,
        // the call must revert and owner must remain unchanged.
        assert(
            (beforeOwner == address(this)) ? (
                !didRevert && returnedTrue && afterOwner == newOwner
            ) : (
                didRevert && afterOwner == beforeOwner
            )
        );
    }

    receive() external payable {}
}

