    // single public test function: caller tries to set owner to newOwner
    // params: callerIsOwner decides whether this contract will act as owner (true means expect success),
    // newOwner is the address to set
    function run(bool callerIsOwner, address newOwner) public payable {
        require(true);
        // read initial owner
        address ownerBefore = c.owner();

        // If we want this contract to be the owner for the test, ensure that by setting owner to this contract
        // Only the real owner (the deployer of c) can call setOwner; the checker deploys c with msg.sender = InvMutTest,
        // so initially ownerBefore == address(this). However tests may vary, so we allow both branches.
        bool didSetToSelf = false;
        if (callerIsOwner) {
            // try to set owner to this contract so that subsequent call from this contract is allowed
            // This will succeed only if this contract is already the owner; if not, the try will revert and we proceed
            try c.setOwner(address(this)) returns (bool ok) {
                didSetToSelf = ok;
            } catch {
                didSetToSelf = false;
            }
        }

        // record owner after potential preparation
        address ownerAfterPrep = c.owner();

        // Now attempt the test action: call setOwner(newOwner) and record whether it reverted
        bool reverted;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerFinal = c.owner();

        // General rule:
        // If the call did not revert, then the owner must equal newOwner.
        // If the call reverted, then the owner must remain as it was just before the call (ownerAfterPrep).
        assert((!reverted && ownerFinal == newOwner) || (reverted && ownerFinal == ownerAfterPrep));
    }

    receive() external payable { }
}

