contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to set owner to a candidate and assert the general rule
    function run(address candidate, address caller) public payable {
        require(true);

        // Read owner before
        address ownerBefore = c.owner();

        // We will simulate two calls from different senders by using the fact that
        // this test contract is the msg.sender for calls to c. To model calls from
        // either the current owner or a non-owner, we use `caller` parameter:
        // if caller == address(this) we act as owner-call, otherwise we act as non-owner-call.
        // To achieve different msg.sender values for c, we rely on the test harness
        // deploying InvMutTest as the same sender that deployed c (as described),
        // so when ownerBefore == address(this) this contract is owner.

        bool reverted;
        bool ret;
        if (caller == address(this)) {
            // attempt as this contract (which may or may not be the owner)
            try c.setOwner(candidate) returns (bool success) {
                reverted = false;
                ret = success;
            } catch {
                reverted = true;
                ret = false;
            }
        } else {
            // We cannot actually change msg.sender for external calls in Solidity here.
            // Instead, model a non-owner call by checking the spec: if caller != address(this)
            // then the call should behave like a call from a non-owner and therefore revert
            // unless the current owner is not address(this) and equals caller. Since we can't
            // perform the call from another address, we only record the expectation.
            // To keep a single assert at the end, set reverted according to whether the
            // actual ownerBefore equals the simulated caller.
            if (ownerBefore == caller) {
                // simulated successful call (ownerBefore equals caller), but since we didn't actually call,
                // we conservatively mark reverted = true to avoid claiming an observed success.
                // However, the general rule will relate observable owner changes to actual call outcome below.
                reverted = true;
                ret = false;
            } else {
                // simulated non-owner must revert
                reverted = true;
                ret = false;
            }
        }

        // Read owner after
        address ownerAfter = c.owner();

        // Assert general rule: if the call did not revert and returned true then the owner changed to candidate;
        // if the call reverted (or did not return true) then owner remains unchanged.
        // This ties observable state change to call success, a meaningful invariant of setOwner.
        assert((!reverted && ret && ownerAfter == candidate) || (reverted || !ret) && ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

