contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry that takes a candidate new owner and an address to attempt the call from
    // We simulate calls by this contract: first we record the initial owner (which is the deployer of C,
    // i.e., this contract), then we try calling setOwner both as the owner (should succeed) and as a non-owner (should revert).
    function run(address candidate, address attacker) public payable {
        require(candidate != address(0)); // avoid trivial zero-address owner

        // read initial owner
        address initialOwner = c.owner();

        // First, when this contract is the owner (it deployed C), calling setOwner should succeed and return true,
        // and owner() should update to candidate.
        bool ok1;
        try c.setOwner(candidate) returns (bool r) {
            ok1 = r;
        } catch {
            ok1 = false;
        }
        address afterOwner1 = c.owner();

        // Revert test: simulate a call from attacker by using a low-level call to c with msg.sender = attacker is not possible here.
        // Instead, we check the general rule by observing that if msg.sender != owner, setOwner must revert.
        // We can test that by calling setOwner again only if this contract is NOT the current owner; to get that state,
        // if this contract remains owner (i.e., afterOwner1 == initialOwner), we attempt to change owner away so that this contract is not owner.
        // Make a second successful change to a different address (addrB) to ensure there's a non-owner to test against.

        // ensure there's some address different from this contract to become owner
        address addrB = attacker;
        if (addrB == address(this) || addrB == address(0)) {
            addrB = candidate;
            if (addrB == address(this) || addrB == address(0)) {
                addrB = address(0x1234);
            }
        }

        // If afterOwner1 is still this contract, try to transfer ownership to addrB so that this contract becomes non-owner.
        bool ok2;
        if (afterOwner1 == address(this)) {
            try c.setOwner(addrB) returns (bool r2) {
                ok2 = r2;
            } catch {
                ok2 = false;
            }
        } else {
            ok2 = false;
        }
        address afterOwner2 = c.owner();

        // Now assert the general rule: For any call to setOwner, it returns true and updates owner when msg.sender == owner,
        // and it reverts (so our observed return is false and owner unchanged) when msg.sender != owner.
        // We express this with observable behaviors we executed above:
        // - ok1 implies that the caller was owner at that time and owner changed to candidate.
        // - if ok1 is false, then owner must not have changed to candidate.
        // - After making a subsequent change (ok2), if ok2 is true then the caller was owner and owner changed to addrB.

        assert(
            // If first call reported success, owner became candidate; otherwise owner is not candidate
            (ok1 && afterOwner1 == candidate || (!ok1 && afterOwner1 != candidate))
            // And if we attempted a second change (ok2 true), owner became addrB; if it failed, owner is not addrB
            && (ok2 && afterOwner2 == addrB || (!ok2 && afterOwner2 != addrB))
        );
    }

    receive() external payable {}
}

