                reverted = false;
                ret = ok;
            } catch {
                reverted = true;
            }
        } else {
            // attempt call from a non-owner by using a low-level call via address(c).call with encoded selector and this contract as caller
            // but we are required to interact with c only via its public/external surface; to simulate a non-owner call, we perform the call through
            // address(c).call from this contract but that still has msg.sender == this contract. We cannot change msg.sender.
            // Instead, to observe the contract behavior for non-owner calls we check that calling setOwner via c will revert when msg.sender != owner.
            // Since this contract is owner initially, we first change owner to some other address so that subsequent call from this contract is non-owner.

            // change owner away from this contract to 'newOwner' to become non-owner
            // This must be a top-level state-changing call
            c.setOwner(newOwner);

            // now this contract is NOT the owner (unless newOwner == address(this)), attempt to setOwner again and capture revert
            try c.setOwner(address(0x1234)) returns (bool ok2) {
                reverted = false;
                ret = ok2;
            } catch {
                reverted = true;
            }
        }

        // read final owner
        address after = c.owner();

        // General rule assertion:
        // - If callAsOwner was true: the call must not revert, must return true, and owner becomes newOwner.
        // - If callAsOwner was false: after first changing owner away, the subsequent call from this contract must revert (so owner unchanged).
        if (callAsOwner) {
            assert(!reverted && ret == true && after == newOwner);
        } else {
            // If newOwner equals this contract's address, then after c.setOwner(newOwner) the contract remains owner, so our later attempt is still by owner.
            // In that case we cannot assert a revert; so we require the general rule only when newOwner != address(this): then the later call must revert and owner stays as newOwner.
            if (newOwner != address(this)) {
                assert(reverted && after == newOwner);
            } else {
                // when newOwner == address(this), both calls are by owner and should succeed and owner stay address(this)
                assert(!reverted && after == address(this));
            }
        }
    }

    receive() external payable { }
}

