    // single public test function: take a candidate new owner and a second candidate for a later attempt
    function run(address newOwner, address laterOwner) public payable {
        // read initial owner
        address beforeOwner = c.owner();

        // Sanity: the freshly deployed C's owner should be this test contract (the deployer in the checker setup).
        // We don't require it, but use it in reasoning below.

        bool firstReverted;
        bool firstRet;

        // Attempt to set owner as the current owner (this contract). This is a top-level state-changing call.
        try c.setOwner(newOwner) returns (bool ok) {
            firstReverted = false;
            firstRet = ok;
        } catch {
            firstReverted = true;
            firstRet = false;
        }

        // Read owner after first attempt
        address midOwner = c.owner();

        bool secondReverted;
        bool secondRet;

        // Now attempt a second call from this contract. If midOwner != address(this) then this contract is not owner and call should revert.
        // If midOwner == address(this) then this contract is owner and call should succeed and update to laterOwner.
        try c.setOwner(laterOwner) returns (bool ok2) {
            secondReverted = false;
            secondRet = ok2;
        } catch {
            secondReverted = true;
            secondRet = false;
        }

        // Read final owner
        address afterOwner = c.owner();

        // General rule assertion combining both steps:
        // - The first call succeeded (did not revert) iff the caller was the owner at that time; when it succeeded it returned true and owner became newOwner.
        // - The second call succeeded iff the caller was the owner at that time (i.e., iff midOwner == address(this)); when it succeeded it returned true and owner became laterOwner.
        // We encode these as implications observable via public surface.
        assert(
            (
                // first call behaved correctly
                (firstReverted == false && firstRet == true && midOwner == newOwner)
                ||
                (firstReverted == true && midOwner == beforeOwner)
            )
            &&
            (
                // second call behaved correctly relative to midOwner
                (secondReverted == false && secondRet == true && afterOwner == laterOwner)
                ||
                (secondReverted == true && afterOwner == midOwner)
            )
        );
    }

    receive() external payable { }
}

