contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a candidate newOwner and a flag indicating whether
    // the call should be made as owner (true) or as non-owner (false).
    // We cannot change msg.sender directly; this contract is the deployer of c, so it starts as owner.
    function run(address newOwner, bool callAsOwner) public payable {
        require(newOwner != address(0));

        // Read owner before the attempted change
        address ownerBefore = c.owner();

        bool reverted;
        bool ret;

        if (callAsOwner) {
            // If we act as owner, InvMutTest is the owner (it deployed c). Call must succeed and return true.
            // Call is a top-level state-changing call.
            try c.setOwner(newOwner) returns (bool ok) {
                reverted = false;
                ret = ok;
            } catch {
                reverted = true;
                ret = false;
            }
        } else {
            // To simulate a non-owner calling setOwner, we perform the call via a low-level call from this contract's fallback.
            // We instruct the contract itself to call c.setOwner by using abi-encoded call in an external call to this contract.
            // Build calldata for setOwner(address)
            bytes memory payload = abi.encodeWithSignature("callSetOwner(address,address)", address(c), newOwner);
            // Call ourselves to execute a non-owner call path (the inner call will use msg.sender = address(this) still),
            // but we need a different msg.sender. Since we cannot create arbitrary senders, instead we attempt to call
            // c.setOwner from a try/catch while first changing ownership away from this contract so that this contract is no longer owner.
            // Make sure ownerBefore is this contract; otherwise we cannot perform the non-owner test meaningfully.
            if (ownerBefore == address(this)) {
                // transfer ownership to some other address (newOwner) so subsequent attempt is by non-owner
                try c.setOwner(newOwner) returns (bool ok1) {
                    // now this contract is no longer owner
                } catch {
                    // if this reverts, we cannot set up the non-owner scenario; mark reverted and skip
                }
            }

            // Now attempt the call which should revert because this contract is not owner
            try c.setOwner(newOwner) returns (bool ok2) {
                reverted = false;
                ret = ok2;
            } catch {
                reverted = true;
                ret = false;
            }
        }

        // Read owner after the attempted change
        address ownerAfter = c.owner();

        // Assertion: If the call was made by the true owner (callAsOwner==true and ownerBefore==address(this)), then it must not revert,
        // must return true, and ownerAfter must equal newOwner. Otherwise (a non-owner call), the call must revert and owner remains unchanged.
        assert(
            // ownerBefore equals this contract means InvMutTest was owner at start
            (
                callAsOwner && ownerBefore == address(this)
            )
            ? (
                reverted == false && ret == true && ownerAfter == newOwner
            )
            : (
                reverted == true && ownerAfter == ownerBefore
            )
        );
    }

    // helper so that abi.encodeWithSignature above compiles if ever used; not called by test directly
    fallback() external payable {}
    receive() external payable {}
}

